"""K-means clustering in the proximity-kernel representation and NMI scoring.

Paper Section 5.1: K-means is applied with the number of clusters set to the
ground-truth number of classes, each experiment is repeated 10 times and the
average NMI is reported.
"""
import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics import normalized_mutual_info_score

from .proximity_kernel import build_representation


def kmeans_nmi_scores(Z, y, n_clusters, seeds, n_init=10, init="k-means++"):
    scores = []
    for seed in seeds:
        km = KMeans(
            n_clusters=n_clusters, init=init, n_init=n_init, random_state=int(seed)
        )
        labels = km.fit_predict(Z)
        scores.append(float(normalized_mutual_info_score(y, labels)))
    return scores


def summarise(scores):
    a = np.asarray(scores, dtype=float)
    return {"mean": float(a.mean()), "std": float(a.std(ddof=0)), "min": float(a.min()), "max": float(a.max())}


def evaluate_grid(X, y, n_clusters, nbins_grid, seeds, mode="restrict", n_init=10):
    """Build the representation for every nbins and score 10 K-means runs."""
    results = {}
    for nbins in nbins_grid:
        Z, diag = build_representation(X, nbins, mode=mode)
        scores = kmeans_nmi_scores(Z, y, n_clusters, seeds, n_init=n_init)
        results[int(nbins)] = {
            "per_seed": scores,
            **summarise(scores),
            "n_features": int(Z.shape[1]),
            "diagnostics": diag,
        }
    return results


def select_best(results):
    best = max(results.items(), key=lambda kv: kv[1]["mean"])
    return int(best[0]), float(best[1]["mean"])

